#[local] Notation "'u'" := bv_unsigned (only parsing).
#[local] Notation w8 x := (word_to_le_bytes 8 x) (only parsing).

(* [comment removed for export] *)
Definition FRX (m : word -> option byte) (s : Z) (ret : word) (regs : bvmap 5 word) : word -> option byte :=
  wbytes (wbytes (wbytes (wbytes (wbytes (wbytes m
    (Z_to_bv 64 (s - 8)) (w8 ret))
    (Z_to_bv 64 (s - 16)) (w8 (getr regs 8)))
    (Z_to_bv 64 (s - 24)) (w8 (getr regs 9)))
    (Z_to_bv 64 (s - 32)) (w8 (getr regs 18)))
    (Z_to_bv 64 (s - 40)) (w8 (getr regs 19)))
    (Z_to_bv 64 (s - 48)) (w8 (getr regs 20)).
Definition framex (s : Z) (ret : word) (r0 : bvmap 5 word) : list (Z * word) :=
  [((s - 8)%Z, ret); ((s - 16)%Z, getr r0 8); ((s - 24)%Z, getr r0 9); ((s - 32)%Z, getr r0 18); ((s - 40)%Z, getr r0 19); ((s - 48)%Z, getr r0 20)].
Lemma FRX_out : forall m s ret regs (x : word), (80 <= s)%Z -> (s < 2 ^ 64)%Z -> ~ (s - 48 <= u x < s)%Z -> FRX m s ret regs x = m x.
