  (* [comment removed for export] *)
  Lemma bx_T8 : forall (fx : FPState) regs r0 m (s pixs skel rkel : Z) (ret : word),
    (80 <= s)%Z -> (s < 2 ^ 64)%Z -> cellsZ m (framex s ret r0) ->
    getr regs 2 = Z_to_bv 64 (s - 80) -> getr regs 8 = Z_to_bv 64 skel -> getr regs 9 = Z_to_bv 64 pixs -> getr regs 18 = Z_to_bv 64 rkel ->
    getr regs 10 = Z_to_bv 64 8 ->
    exists regs',
      msteps SEGS (@mkst fx regs (0x2e418 : word) m rom) (@mkst fx regs' (0x2e578 : word) m rom)
      /\ getr regs' 2 = Z_to_bv 64 s /\ getr regs' 1 = ret /\ getr regs' 10 = Z_to_bv 64 pixs /\ getr regs' 11 = Z_to_bv 64 skel /\ getr regs' 12 = Z_to_bv 64 rkel
      /\ (forall x, In x [8; 9; 18; 19; 20]%bv -> getr regs' x = getr r0 x)
