  Definition bx_R1_stmt (pc pc' : word) (ra' : Z) : Prop := forall (fx : FPState) regs m (s t skel rkel : Z),
    (80 <= s)%Z -> (s < 2 ^ 64)%Z -> store_ok SEGS m (Z_to_bv 64 (s - 56)) 8 = true ->
    getr regs 2 = Z_to_bv 64 (s - 80) -> getr regs 10 = Z_to_bv 64 t -> getr regs 8 = Z_to_bv 64 skel -> getr regs 18 = Z_to_bv 64 rkel ->
    exists regs',
      msteps SEGS (@mkst fx regs pc m rom) (@mkst fx regs' pc' (wbytes m (Z_to_bv 64 (s - 56)) (w8 (Z_to_bv 64 t))) rom)
      /\ getr regs' 2 = Z_to_bv 64 (s - 80) /\ getr regs' 10 = Z_to_bv 64 t /\ getr regs' 11 = Z_to_bv 64 skel /\ getr regs' 12 = Z_to_bv 64 rkel
      /\ getr regs' 1 = Z_to_bv 64 ra'
      /\ regs_agree (fun x => In x [1; 11; 12]%list) regs regs'.
