  Lemma bx_F2 : forall (fx : FPState) regs m (s : Z),
    getr regs 2 = Z_to_bv 64 (s - 80) ->
    exists regs',
      msteps SEGS (@mkst fx regs (0x2e560 : word) m rom) (@mkst fx regs' (0x19428 : word) m rom)
      /\ getr regs' 2 = Z_to_bv 64 (s - 80) /\ getr regs' 10 = Z_to_bv 64 (s - 72) /\ getr regs' 1 = Z_to_bv 64 0x2e568
      /\ regs_agree (fun x => In x [1; 10]%list) regs regs'.
Proof.
